// Filtra eventos da Evolution API e extrai os dados essenciais da mensagem
const body = $json.body ?? $json;
const event = String(body.event || '').toLowerCase().replace('.', '_');
if (event && event !== 'messages_upsert') return [];

const data = body.data ?? body;
const key = data.key ?? {};
const jid = key.remoteJid || '';
if (!jid) return [];
if (jid.endsWith('@g.us') || jid === 'status@broadcast') return [];

if (key.fromMe === true) {
  const mm = data.message ?? {};
  const txt = String(
    mm.conversation ||
    (mm.extendedTextMessage && mm.extendedTextMessage.text) ||
    (mm.imageMessage && mm.imageMessage.caption) ||
    (mm.documentMessage && mm.documentMessage.caption) ||
    ''
  );

  // A Evolution identifica disparos feitos por API/automações como source "unknown".
  // Somente mensagens originadas de um dispositivo humano pausam a ANA.
  // O comando #assumir é um fallback explícito para instalações sem source confiável.
  const source = String(data.source || '').trim().toLowerCase();
  const origemHumana = ['android', 'ios', 'web'].includes(source);
  const comandoHumano = /^\s*(#assumir|#humano|\/assumir)\b/i.test(txt);

  if (!origemHumana && !comandoHumano) return [];

  return [{
    json: {
      humano: true,
      phone: jid.split('@')[0],
      conteudo: txt,
      source
    }
  }];
}

const phone = jid.split('@')[0];
const m = data.message ?? {};
let msgType = 'texto', texto = '', midiaCaption = '';

if (m.conversation) { texto = m.conversation; }
else if (m.extendedTextMessage && m.extendedTextMessage.text) { texto = m.extendedTextMessage.text; }
else if (m.imageMessage) { msgType = 'imagem'; midiaCaption = m.imageMessage.caption || ''; }
else if (m.audioMessage) { msgType = 'audio'; }
else if (m.documentMessage || m.documentWithCaptionMessage) {
  const dm = m.documentMessage ?? (m.documentWithCaptionMessage.message || {}).documentMessage ?? {};
  midiaCaption = dm.caption || '';
  if (String(dm.mimetype || '').includes('pdf')) {
    msgType = 'pdf';
  } else {
    msgType = 'texto';
    texto = (midiaCaption ? midiaCaption + ' ' : '') +
      '[Paciente enviou um arquivo que não consigo abrir por aqui — peça para enviar como foto ou PDF]';
  }
}
else if (m.stickerMessage) {
  msgType = 'texto';
  texto = '[Paciente enviou uma figurinha]';
}
else return [];

const placeholders = {
  imagem: '[Paciente enviou uma imagem — processando]',
  audio: '[Paciente enviou um áudio — processando]',
  pdf: '[Paciente enviou um PDF — processando]'
};

const conteudoInicial = msgType === 'texto'
  ? texto
  : ((midiaCaption ? midiaCaption + ' ' : '') + placeholders[msgType]);

return [{
  json: {
    phone,
    jid,
    pushName: data.pushName || '',
    messageId: key.id || String(Date.now()),
    msgType,
    texto,
    midiaCaption,
    conteudoInicial
  }
}];

const f = $('Filtrar Eventos').first().json;
const r = $json;
const b64 = r.base64 ?? (r.media && r.media.base64) ?? (r.data && r.data.base64);
const mime = String(r.mimetype ?? (r.media && r.media.mimetype) ?? 'image/jpeg').split(';')[0];
const instr = 'Extraia somente dados de um pedido médico. Não invente. Se não for pedido médico, informe isso em observacoes.';
const fallback = { legivel: false, exames: [], observacoes: 'falha no download da imagem' };
const content = b64
  ? [{ type: 'input_image', image_url: 'data:' + mime + ';base64,' + b64, detail: 'high' }, { type: 'input_text', text: instr }]
  : [{ type: 'input_text', text: 'Retorne exatamente: ' + JSON.stringify(fallback) }];
const schema = { type: 'object', additionalProperties: false, properties: {
  legivel: { type: 'boolean' },
  exames: { type: 'array', items: { type: 'string' } },
  observacoes: { type: 'string' }
}, required: ['legivel', 'exames', 'observacoes'] };
const body = { model: 'gpt-5.6-luna', reasoning: { effort: 'none' }, max_output_tokens: 500,
  input: [{ role: 'user', content }], text: { format: { type: 'json_schema', name: 'pedido_medico', strict: true, schema } }, store: false };
return [{ json: { openai_body: body, phone: f.phone } }];

