try {
  const txt = ($json.output || []).flatMap(o => o.content || []).filter(c => c.type === 'output_text').map(c => c.text).join('\n');
  if (txt) parsed = Object.assign(parsed, JSON.parse(txt));
} catch (e) {}
const lista = (parsed.exames || []).filter(Boolean);
const cap = f.midiaCaption ? f.midiaCaption + '\n' : '';
let texto_para_ia;
if (lista.length) {
  texto_para_ia = cap + '[O paciente enviou imagem de pedido médico. Exames identificados: ' + lista.join('; ') + '. Obs: ' + (parsed.observacoes || '-') + ' — use consultar_precos com TODOS os exames e responda com o orçamento. Exame sem preço: *valor a consultar*.]';
} else {
  texto_para_ia = cap + '[Não foi possível identificar exames com clareza' + (parsed.observacoes ? ' (' + parsed.observacoes + ')' : '') + '. Peça uma nova foto mais nítido.]';
}
return [{ json: { phone: f.phone, messageId: f.messageId, texto_para_ia, midia: 'imagem' } }];

