  texto_para_ia = cap + '[O paciente enviou pdf de pedido médico. Exames identificados: ' + lista.join('; ') + '. Obs: ' + (parsed.observacoes || '-') + ' — use consultar_precos com TODOS os exames e responda com o orçamento. Exame sem preço: *valor a consultar*.]';
} else {
  texto_para_ia = cap + '[Não foi possível identificar exames com clareza' + (parsed.observacoes ? ' (' + parsed.observacoes + ')' : '') + '. Peça um novo PDF mais nítido.]';
}
return [{ json: { phone: f.phone, messageId: f.messageId, texto_para_ia, midia: 'pdf' } }];

const histAll = $('Carregar Histórico').all().map(i => i.json);
const hist = histAll.slice(-12);
const sys = String($('Carregar System Prompt').first().json.valor || '').replace(/\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const lead = $('Upsert Lead').first().json;
const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
const ctx = [
  '[CONTEXTO INTERNO]',
  'Agora: ' + agora + ' (America/Sao_Paulo)',
  'Nome: ' + (lead.nome || 'não informado'),
  lead.resumo_interno ? 'Resumo anterior: ' + lead.resumo_interno : null,
  'Preços: use consultar_precos antes de citar valores; nunca invente.',
  'Agenda: não confirme disponibilidade; colete dados e escale para confirmação humana.',
  'Finalize com ###DADOS### seguido do JSON contratual em uma linha.'
].filter(Boolean).join('\n');
const msgs = [];
for (const h of hist) {
  const role = h.role === 'assistant' ? 'assistant' : 'user';
  const c = String(h.conteudo || '').trim();
  if (!c) continue;
  if (msgs.length && msgs[msgs.length - 1].role === role) msgs[msgs.length - 1].content += '\n\n' + c;
  else msgs.push({ role, content: c });
}
while (msgs.length && msgs[0].role !== 'user') msgs.shift();
if (!msgs.length) msgs.push({ role: 'user', content: '(primeiro contato do paciente)' });
if (msgs[msgs.length - 1].role === 'user') msgs[msgs.length - 1].content += '\n\n' + ctx;
else msgs.push({ role: 'user', content: ctx });
const tools = [{ type: 'function', name: 'consultar_precos',
  description: 'Consulta a tabela oficial. Use antes de informar valores e envie todos os exames de uma vez.',
  parameters: { type: 'object', additionalProperties: false, properties: {
    exames: { type: 'array', items: { type: 'string' }, description: 'Nomes completos dos exames' }
  }, required: ['exames'] }, strict: true
}];
const body = { model: 'gpt-5.6-luna', instructions: sys, input: msgs, tools, tool_choice: 'auto',
  reasoning: { effort: 'low' }, max_output_tokens: 1200, store: false };
return [{ json: { openai_body: body, phone: lead.phone } }];

const resp = $json;
const call = (resp.output || []).find(i => i.type === 'function_call' && i.name === 'consultar_precos');
let args = {};
try { args = JSON.parse((call && call.arguments) || '{}'); } catch (e) {}
const exames = (args.exames || []).filter(Boolean);
return [{ json: { pg_payload: JSON.stringify({ exames }), tool_call_id: (call && call.call_id) || '', phone: $('Montar Payload').first().json.phone } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.nome_exame);
const first = $('Chamar Ana').first().json;
const base = $('Montar Payload').first().json.openai_body;
const callId = $('Preparar Consulta').first().json.tool_call_id;
const resultado = rows.length
  ? JSON.stringify(rows)
  : JSON.stringify({ resultado: 'nenhum exame encontrado na tabela', instrucao: 'Não invente valor; informe valor a consultar e escale somente conforme as regras do sistema.' });
const priorOutput = (first.output || []).filter(i => i.type === 'function_call');
const body = Object.assign({}, base, { tool_choice: 'none', input: base.input.concat(priorOutput, [
  { type: 'function_call_output', call_id: callId, output: resultado }
]) });
return [{ json: { openai_body: body, phone: $('Montar Payload').first().json.phone } }];

// Separa a mensagem do paciente do bloco ###DADOS### e calcula o próximo follow-up
const resp = $json;
const phone = $('Montar Payload').first().json.phone;
let texto = '';
try { texto = (resp.output || []).flatMap(o => o.content || []).filter(c => c.type === 'output_text').map(c => c.text).join('\n').trim(); } catch (e) {}
let dados = { temperatura: 'morno', funil: 'meio', consciencia: null, intencao: 'outro', exames_mencionados: [], convenio: null, agendamento: { status: 'nenhum', data: null, turno: null }, opt_out: false, proxima_acao: 'aguardar_resposta', escalar: false, motivo_escalada: null, resumo_interno: '' };
let msg = texto;
const ix = texto.indexOf('###DADOS###');
if (ix >= 0) {
  msg = texto.slice(0, ix).trim();
  const m = texto.slice(ix).match(/\{[\s\S]*\}/);
  if (m) { try { dados = Object.assign(dados, JSON.parse(m[0])); } catch (e) {} }
}
if (!msg) {
  msg = 'Só um instante, vou confirmar uma informação com a equipe e já te retorno 😊';
  dados.escalar = true;
  dados.motivo_escalada = dados.motivo_escalada || 'Falha na geração de resposta da IA — verificar execução no N8N';
}
const ci = parseInt(dados.consciencia, 10);
dados.consciencia = (ci >= 1 && ci <= 4) ? ci : null;
if (!dados.agendamento || typeof dados.agendamento !== 'object') dados.agendamento = { status: 'nenhum', data: null, turno: null };
const st = dados.agendamento.status || 'nenhum';
const mapa = { follow_up_d1: 1, follow_up_d3: 3, follow_up_d7: 7, xeque_mate: 7, follow_up_d30: 16 };
let dias = mapa[dados.proxima_acao];
if (dias === undefined) dias = (st !== 'confirmado' && !['agendado', 'encerrar', 'escalar'].includes(dados.proxima_acao)) ? 1 : null;
if (dados.opt_out || dados.escalar || ['agendado', 'encerrar', 'escalar'].includes(dados.proxima_acao) || st === 'confirmado') dias = null;
const due = dias ? new Date(Date.now() + dias * 86400000).toISOString() : null;
const pausar = !!dados.escalar && /(emerg|reclama|conflit|lgpd|humano|urgên|urgenc)/i.test(String(dados.motivo_escalada || ''));
const bolhas = msg.split(/\n{2,}/).map(t => t.trim()).filter(Boolean)
  .map(t => ({ texto: t, delay: Math.min(6000, Math.max(1500, t.length * 35)) }));
return [{ json: {
  phone, mensagem: msg, dados, bolhas, followup_due: due, pausar,
  pg_msg: JSON.stringify({ phone, conteudo: msg, dados }),
  pg_lead: JSON.stringify({ phone, temperatura: dados.temperatura, funil: dados.funil, consciencia: dados.consciencia, intencao: dados.intencao, exames: dados.exames_mencionados || [], convenio: dados.convenio, agendamento: dados.agendamento, opt_out: !!dados.opt_out, proxima_acao: dados.proxima_acao, followup_due: due, escalado: !!dados.escalar, motivo_escalada: dados.motivo_escalada, resumo_interno: dados.resumo_interno || '', pausar }),
} }];
